/**
 * Offline support notices, shown as a small bar at the bottom of every page (rendered
 * by Layout.jsx): "New version available" with a Reload button when the service worker
 * has an update waiting, and a one-time "Install" offer that can be dismissed for good.
 * The service worker itself is generated by vite-plugin-pwa (see vite.config.js).
 */
import { useEffect, useState } from 'react'
import { useRegisterSW } from 'virtual:pwa-register/react'
import { Download, RefreshCw, X } from 'lucide-react'

// Remembers that the install offer was answered, so it appears only once per browser.
const installAnsweredKey = 'gov-exam-portal:install-answered'

/** True when the install offer was already dismissed or accepted in this browser. */
function wasInstallAnswered() {
  try {
    return window.localStorage.getItem(installAnsweredKey) === '1'
  } catch {
    // Storage blocked (private window): offer once per visit instead.
    return false
  }
}

/** Records that the install offer needs no further showing; storage errors are ignored. */
function rememberInstallAnswered() {
  try {
    window.localStorage.setItem(installAnsweredKey, '1')
  } catch {
    // Storage unavailable: nothing to remember.
  }
}

/** Update notice and one-time install offer. Renders nothing when neither applies. */
export function PwaPrompts() {
  const {
    needRefresh: [isUpdateWaiting],
    updateServiceWorker,
  } = useRegisterSW()
  // The browser's install event, kept so the offer can trigger the real install dialog.
  const [installEvent, setInstallEvent] = useState(null)

  useEffect(() => {
    const handleInstallable = (event) => {
      // Stop the browser's own mini banner; the site shows its offer instead.
      event.preventDefault()
      if (!wasInstallAnswered()) setInstallEvent(event)
    }
    window.addEventListener('beforeinstallprompt', handleInstallable)
    return () => window.removeEventListener('beforeinstallprompt', handleInstallable)
  }, [])

  const closeInstallOffer = () => {
    rememberInstallAnswered()
    setInstallEvent(null)
  }
  const install = () => {
    installEvent.prompt()
    closeInstallOffer()
  }

  if (isUpdateWaiting) {
    return (
      <div className="app-notice" role="status">
        <span>New version available.</span>
        <button type="button" className="button button-primary button-small" onClick={() => updateServiceWorker(true)}>
          <RefreshCw size={14} aria-hidden="true" /> Reload
        </button>
      </div>
    )
  }
  if (installEvent) {
    return (
      <div className="app-notice" role="region" aria-label="Install the app">
        <span>Install Sarkari Shiksha to use it offline.</span>
        <button type="button" className="button button-primary button-small" onClick={install}>
          <Download size={14} aria-hidden="true" /> Install
        </button>
        <button type="button" className="icon-button" onClick={closeInstallOffer} title="Do not show again">
          <X size={16} aria-hidden="true" />
          <span className="visually-hidden">Dismiss</span>
        </button>
      </div>
    )
  }
  return null
}
